from __future__ import annotations

from typing import TYPE_CHECKING

import pytest
from ds.ai.model import model_label, seat_usage_tracked, spend_tracked

if TYPE_CHECKING:
    from tests.services.ui.e2e.conftest import App


def _debug_tabs(app: App) -> list[str]:
    """The debug panel's tabs, by their labels, after opening it from the title bar."""
    app.page.locator('button[title^="Debug log"]').click()
    app.page.wait_for_selector(".dbg-tab")
    return app.page.locator(".dbg-tab").all_inner_texts()


@pytest.mark.smoke
@pytest.mark.usefixtures("ai_controls")
def test_the_title_bar_names_the_model(app: App) -> None:
    assert app.page.locator(".chat-model").inner_text() == model_label()


@pytest.mark.usefixtures("ai_controls")
def test_dollars_are_on_the_page_only_for_a_model_billed_in_them(app: App) -> None:
    meter = app.page.locator(".ctx-meter").first.inner_text()
    tabs = _debug_tabs(app)
    assert "Agents" in tabs  # the panel itself is there
    if spend_tracked():
        assert "Spend" in tabs
        assert app.page.locator(".spend-meter-btn").count() == 1
        assert app.page.locator(".copilot-box").count() == 0
        assert "this session $" in meter
    else:
        assert "Spend" not in tabs
        assert app.page.locator(".spend-meter-btn").count() == 0
        assert "$" not in meter
        assert meter.startswith("context")


@pytest.mark.smoke
@pytest.mark.usefixtures("ai_controls")
def test_a_copilot_model_shows_the_seats_premium_quota_with_a_refresh_button(app: App) -> None:
    if not seat_usage_tracked():
        pytest.skip("the model isn't a GitHub Copilot one")
    box = app.page.locator(".copilot-box")
    assert box.count() == 1
    assert box.locator(".ctx-meter").inner_text().startswith("premium ")
    # the percent is what shows; the count takes its place on hover, as in the context meter
    assert box.locator(".ctx-pct").is_visible()
    assert not box.locator(".ctx-tokens").is_visible()
    box.locator(".ctx-meter").hover()
    assert box.locator(".ctx-tokens").is_visible()
    assert not box.locator(".ctx-pct").is_visible()
    # its own button reads it again (not clicked here: that is a request to GitHub)
    assert box.locator('button[aria-label="Refresh Copilot usage"]').count() == 1
    assert box.locator(".spend-as-of").inner_text().startswith("as of ")


@pytest.mark.smoke
@pytest.mark.usefixtures("ai_controls")
def test_the_context_bar_has_no_fill_before_anything_is_sent(app: App) -> None:
    fill = app.page.locator(".titlebar > .ctx-meter .ctx-bar i")
    assert fill.get_attribute("data-empty") == "true"  # a fresh session: 0 tokens
    assert fill.bounding_box()["width"] == 0
